window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ccb92caf541927eb"]={"versions": [{"id": "FIG-ccb92caf541927eb", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Methodikdiagramm zur Ableitung eines konkreten VFB-Timings (Virtual Function Bus Timing) aus einem VFB-Timing-Blueprint gemäß AUTOSAR TPS Standardization Template. Das Diagramm stellt die Transformation und Verknüpfung von standardisierten Blueprint-Beschreibungen (VFB Timing Blueprint und Port Prototype Blueprint) hin zu einer konkreten Software-Komponenten-Instanz (<code>SwcA</code>) und deren zugehörigem VFB-Timing (<code>VFB Timing SwcA</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptbereiche, die über den Transformationsschritt „Derive Blueprint“ verknüpft sind:</p>\n<ul class=\"fig-list\"><li><strong>Blueprint-Ebene (blau umrandet):</strong>\n<ul class=\"fig-list\"><li><code>VFB Timing Blueprint</code> (gestrichelt hinterlegte Entitäten):\n<ul class=\"fig-list\"><li><code>pet_AccrPedlRat</code>: Timing Constraint (TC) vom Typ Periodic Event Triggering (PET) mit den Parametern Periode P = 10\\,ms und Jitter J = 1\\,ms.\n</li><li><code>tde_Vdpr_AccrPedlRat</code>: Timing Description Event (TDE) für ein empfangenes Datenelement (VDPR: Variable Data Prototype Received), referenziert durch <code>pet_AccrPedlRat</code>.\n</li></ul>\n</li><li><code>Blueprint</code> (struktureller Kontext):\n<ul class=\"fig-list\"><li><code>AccrPedlRat</code>: Port Prototype Blueprint (gestrichelter R-Port).\n</li><li><code>AccrPedlRat1</code>: Sender/Receiver (S/R) Port Interface <code>AccrPedlRat</code>.\n</li><li>Das TDE referenziert den Port Prototype Blueprint und das Datenelement des Port Interfaces.\n</li></ul>\n</li></ul>\n</li><li><strong>Konkrete Modellebene (schwarz umrandet):</strong>\n<ul class=\"fig-list\"><li><code>SwcA</code>: Konkrete Software-Komponente mit dem Required Port <code>rpAccrPedlRat</code> (typisiert über das S/R Port Interface <code>AccrPedlRat1</code> bzw. Datenelement <code>AccrPedlRat</code>).\n</li><li><code>VFB Timing SwcA</code>:\n<ul class=\"fig-list\"><li><code>tcAccrPedlRatSwcA</code>: Konkretes Timing Constraint (TC, PET: P = 10\\,ms, J = 1\\,ms).\n</li><li><code>evAccrPedlRatSwcA</code>: Konkretes Timing Description Event (TDE, VDPR).\n</li><li>Assoziationen verbinden das VFB-Timing mit <code>SwcA</code>, das TDE mit dem Port <code>rpAccrPedlRat</code> und das Datenelement des Port Interfaces.\n</li></ul>\n</li></ul>\n</li><li><strong>Legende:</strong> Führt die relevanten Timing- und VFB-Kürzel auf (TDE, TDEC, TC, VDPR, VDPS, S/R, PET, AC, P, J).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Dargestellt ist ein modellbasierter Ableitungsprozess („Derive Blueprint“):</p>\n<ol class=\"fig-list\"><li>Auf Blueprint-Ebene wird eine Schablone für ein periodisches Empfangsereignis (<code>pet_AccrPedlRat</code>) auf Basis einer Port-Vorlage (<code>AccrPedlRat</code>) und eines Interface-Prototyps spezifiziert.\n</li><li>Über die Blueprint-Ableitung werden sowohl die strukturelle Komponente (<code>SwcA</code> mit <code>rpAccrPedlRat</code>) als auch die zugehörigen Timing-Beschreibungen (<code>VFB Timing SwcA</code>) instanziiert bzw. abgeleitet.\n</li><li>Im Zielmodell überwacht das Timing Constraint <code>tcAccrPedlRatSwcA</code> das konkrete Empfangsereignis <code>evAccrPedlRatSwcA</code> am Port <code>rpAccrPedlRat</code> mit einer Soll-Periode von 10\\,ms und maximalem Jitter von 1\\,ms.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die normative Methodik der AUTOSAR-Standardisierung zur Wiederverwendung von Timing-Anforderungen mittels Blueprints. Entwickler müssen bei der Ableitung eines VFB-Timings sicherstellen, dass die im Blueprint definierten Constraints (hier PET-Parameter P und J) sowie die Referenzketten vom Timing Description Event auf die realen Port-Prototypen und Variablen-Datenprototypen der Zielkomponente konsistent aufgelöst und gebunden werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-05bcd5116893f5a1", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Methodikdiagramm zur Ableitung eines konkreten VFB-Timings (Virtual Function Bus Timing) aus einem VFB-Timing-Blueprint gemäß AUTOSAR TPS Standardization Template. Das Diagramm stellt die Transformation und Verknüpfung von standardisierten Blueprint-Beschreibungen (VFB Timing Blueprint und Port Prototype Blueprint) hin zu einer konkreten Software-Komponenten-Instanz (<code>SwcA</code>) und deren zugehörigem VFB-Timing (<code>VFB Timing SwcA</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptbereiche, die über den Transformationsschritt „Derive Blueprint“ verknüpft sind:</p>\n<ul class=\"fig-list\"><li><strong>Blueprint-Ebene (blau umrandet):</strong>\n<ul class=\"fig-list\"><li><code>VFB Timing Blueprint</code> (gestrichelt hinterlegte Entitäten):\n<ul class=\"fig-list\"><li><code>pet_AccrPedlRat</code>: Timing Constraint (TC) vom Typ Periodic Event Triggering (PET) mit den Parametern Periode P = 10\\,ms und Jitter J = 1\\,ms.\n</li><li><code>tde_Vdpr_AccrPedlRat</code>: Timing Description Event (TDE) für ein empfangenes Datenelement (VDPR: Variable Data Prototype Received), referenziert durch <code>pet_AccrPedlRat</code>.\n</li></ul>\n</li><li><code>Blueprint</code> (struktureller Kontext):\n<ul class=\"fig-list\"><li><code>AccrPedlRat</code>: Port Prototype Blueprint (gestrichelter R-Port).\n</li><li><code>AccrPedlRat1</code>: Sender/Receiver (S/R) Port Interface <code>AccrPedlRat</code>.\n</li><li>Das TDE referenziert den Port Prototype Blueprint und das Datenelement des Port Interfaces.\n</li></ul>\n</li></ul>\n</li><li><strong>Konkrete Modellebene (schwarz umrandet):</strong>\n<ul class=\"fig-list\"><li><code>SwcA</code>: Konkrete Software-Komponente mit dem Required Port <code>rpAccrPedlRat</code> (typisiert über das S/R Port Interface <code>AccrPedlRat1</code> bzw. Datenelement <code>AccrPedlRat</code>).\n</li><li><code>VFB Timing SwcA</code>:\n<ul class=\"fig-list\"><li><code>tcAccrPedlRatSwcA</code>: Konkretes Timing Constraint (TC, PET: P = 10\\,ms, J = 1\\,ms).\n</li><li><code>evAccrPedlRatSwcA</code>: Konkretes Timing Description Event (TDE, VDPR).\n</li><li>Assoziationen verbinden das VFB-Timing mit <code>SwcA</code>, das TDE mit dem Port <code>rpAccrPedlRat</code> und das Datenelement des Port Interfaces.\n</li></ul>\n</li></ul>\n</li><li><strong>Legende:</strong> Führt die relevanten Timing- und VFB-Kürzel auf (TDE, TDEC, TC, VDPR, VDPS, S/R, PET, AC, P, J).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Dargestellt ist ein modellbasierter Ableitungsprozess („Derive Blueprint“):</p>\n<ol class=\"fig-list\"><li>Auf Blueprint-Ebene wird eine Schablone für ein periodisches Empfangsereignis (<code>pet_AccrPedlRat</code>) auf Basis einer Port-Vorlage (<code>AccrPedlRat</code>) und eines Interface-Prototyps spezifiziert.\n</li><li>Über die Blueprint-Ableitung werden sowohl die strukturelle Komponente (<code>SwcA</code> mit <code>rpAccrPedlRat</code>) als auch die zugehörigen Timing-Beschreibungen (<code>VFB Timing SwcA</code>) instanziiert bzw. abgeleitet.\n</li><li>Im Zielmodell überwacht das Timing Constraint <code>tcAccrPedlRatSwcA</code> das konkrete Empfangsereignis <code>evAccrPedlRatSwcA</code> am Port <code>rpAccrPedlRat</code> mit einer Soll-Periode von 10\\,ms und maximalem Jitter von 1\\,ms.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die normative Methodik der AUTOSAR-Standardisierung zur Wiederverwendung von Timing-Anforderungen mittels Blueprints. Entwickler müssen bei der Ableitung eines VFB-Timings sicherstellen, dass die im Blueprint definierten Constraints (hier PET-Parameter P und J) sowie die Referenzketten vom Timing Description Event auf die realen Port-Prototypen und Variablen-Datenprototypen der Zielkomponente konsistent aufgelöst und gebunden werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ccb92caf541927eb", "to": "FIG-05bcd5116893f5a1", "fr": "R4.2.2", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
